"""Numerical snapshots generated by the untouched published-release checkout."""

import json
from pathlib import Path

import jax.numpy as np
import pytest

from dLux import compat
from scripts.compare_release import observations

REFERENCE = json.loads(Path(__file__).with_name("reference_outputs.json").read_text())


@pytest.fixture(scope="module")
def results():
    return observations(compat, migrated=True)


@pytest.mark.parametrize("name", REFERENCE["arrays"])
def test_released_numerical_output(name, results):
    expected = REFERENCE["arrays"][name]
    values = np.array(expected["real"]) + 1j * np.array(expected["imag"])
    values = values.reshape(expected["shape"])
    actual = np.asarray(results[name])
    assert actual.shape == values.shape
    # The snapshots used JAX 0.7.2. On 0.11.2 the untouched 0.15.1 release
    # reproduces our Zernike/polike arrays bit-for-bit, but differs from its own
    # snapshots by up to 1.91e-6 near polynomial cancellations. Keep this allowance
    # confined to those dimensionless modes; optical fields retain their tolerance.
    atol = 2e-6 if name in ("zernikes", "polikes") else 1e-7
    # Matrix-based coordinate composition changes float32 rounding at soft edges.
    # The same nested-aperture comparison agrees to 2.2e-15 in float64.
    if name.startswith("nested_apertures"):
        atol = 2e-6
    assert np.allclose(actual, values, rtol=5e-6, atol=atol)


@pytest.mark.parametrize("name", ("core", "layers", "utils"))
def test_released_public_namespace_is_complete(name):
    module = compat if name == "core" else getattr(compat, name)
    assert set(REFERENCE["api"][name]) <= set(module.__all__)
    assert all(hasattr(module, attr) for attr in REFERENCE["api"][name])
